use tree_sitter::Node;

const COMMENT: &str = "comment";
const PACKAGE_CLAUSE: &str = "package_clause";
const MARKERS: [&str; 4] = [
    "code generated",
    "do not edit",
    "autogenerated file",
    "* generated by: swagger codegen ",
];

pub fn is_generated(root: Node<'_>, source: &[u8]) -> bool {
    let mut cursor = root.walk();
    let children: Vec<Node<'_>> = root.children(&mut cursor).collect();
    let package = children.iter().position(|child| child.kind() == PACKAGE_CLAUSE);
    let header_end = package
        .and_then(|package| {
            children
                .iter()
                .skip(package.saturating_add(1))
                .find(|child| child.is_named() && child.kind() != COMMENT)
        })
        .map_or(source.len(), Node::start_byte);
    let header = children
        .iter()
        .filter(|child| child.kind() == COMMENT && child.start_byte() < header_end)
        .filter_map(|comment| comment.utf8_text(source).ok())
        .collect::<Vec<_>>()
        .join("\n")
        .to_lowercase();
    MARKERS.iter().any(|marker| header.contains(marker))
}
